package com.mfg.qms.controller;import com.mfg.common.api.*;import com.mfg.common.exception.BizException;import com.mfg.qms.entity.Inspection;import com.mfg.qms.repo.InspectionRepository;import com.mfg.security.config.CurrentUser;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;
/** 质量结论不是备注：不合格会成为返工/报废/隔离的业务起点。 */
@RestController @RequestMapping("/api/qms/inspections") @RequiredArgsConstructor public class InspectionController{private final InspectionRepository repo;@GetMapping public ApiResponse<Page<Inspection>> page(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(repo.findAll(PageRequest.of(Math.max(0,page-1),Math.min(size,200))));}@PostMapping public ApiResponse<Inspection> create(@RequestBody Inspection i){if(repo.existsByInspectionNo(i.getInspectionNo()))throw BizException.of(ErrorCode.MASTER_DATA_ALREADY_EXISTS,"检验单号已存在");i.setResult("PENDING");i.setInspectDate(LocalDate.now());i.setInspectorCode(CurrentUser.usernameOrSystem());return ApiResponse.ok(repo.save(i));}@PostMapping("/{id}/judge")public ApiResponse<Inspection> judge(@PathVariable Long id,@RequestParam BigDecimal qualifiedQty,@RequestParam BigDecimal defectQty,@RequestParam String result){Inspection i=repo.findById(id).orElseThrow(()->BizException.notFound("检验单",id));if(!"PENDING".equals(i.getResult()))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"检验结论已生成");if(qualifiedQty.add(defectQty).compareTo(i.getInspectedQty())!=0)throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"合格数与不合格数之和必须等于送检数");if(!java.util.Set.of("PASSED","FAILED","CONCESSION","REWORK").contains(result))throw BizException.of(ErrorCode.MASTER_DATA_INVALID_STATE,"非法检验结论");i.setQualifiedQty(qualifiedQty);i.setDefectQty(defectQty);i.setDefectRate(i.getInspectedQty().signum()==0?BigDecimal.ZERO:defectQty.divide(i.getInspectedQty(),4,RoundingMode.HALF_UP));i.setResult(result);return ApiResponse.ok(repo.save(i));}}
